using System.Diagnostics;
using System.Text.Json;
using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Appearance;
int count=args.Length>0?int.Parse(args[0]):30;
var report=new Dictionary<string,object>{["synthetic_registered_people"]=count,["historical_people"]=NationalPersonnel.Catalog.People.Length,["route_nodes"]=NationalRoutes.Nodes.Length,["route_edges"]=NationalRoutes.Edges.Length,["scope"]="Synthetic registered ronin; selected actor travels. Not nationwide NPC AI or simultaneous armies."};
T Measure<T>(string key,Func<T> run){GC.Collect();long alloc=GC.GetTotalAllocatedBytes(true);var sw=Stopwatch.StartNew();var value=run();sw.Stop();report[key]=new{milliseconds=sw.Elapsed.TotalMilliseconds,allocated_bytes=GC.GetTotalAllocatedBytes(true)-alloc};Console.WriteLine(JsonSerializer.Serialize(new{phase=key,result=report[key]}));return value;}
var records=Enumerable.Range(0,count).Select(i=>new RegisteredOfficer($"created:capacity-{i:D5}",null,$"測定専用{i:D5}",1520,new(50,50,50,50),StartTemplate.Ronin,NationalRoutes.Sites[i%NationalRoutes.Sites.Length].Id.Value,null,null,AppearanceCatalog.Default(1))).ToArray();
var normalized=Measure("normalize",()=>NewGameWorld.Normalize(records));
var baseline=NewGameWorld.Scenario();
var request=new WorldSetupRequest(normalized,[]);
var preview=Measure("preview",()=>NewGameSetup.Preview(baseline,request));
if(!preview.IsEligible())throw new InvalidDataException(string.Join(",",preview.Errors));
var confirmed=Measure("confirm",()=>NewGameSetup.Confirm(baseline,request,preview));
var world=Measure("create",()=>NewGameWorld.Create(confirmed,normalized,"person:nobunaga",personalAuthorityLayout:args.Contains("compact")?NewGameWorld.CompactPersonalAuthority:null));
report["compact"]=args.Contains("compact");report["start_hash"]=ContractJson.CanonicalHash(world);report["actual_world_people"]=world.Characters.Length;report["grants"]=world.Grants.Length;
var session=Measure("session",()=>new WorldSession(world));
var move=Measure("submit",()=>session.Submit(TravelWorld.Move(session.DiagnosticSnapshot(),"request:capacity-move","fork"),session.Revision));
if(move.Code!=ResultCode.Accepted)throw new InvalidDataException(move.ToString());
Measure("advance_5_seconds",()=>{while(session.Seconds<5){session.SetPaused(false);session.AdvanceTo(5);}return session.Seconds;});
session.SetPaused(true);
var snapshot=Measure("snapshot",()=>session.DiagnosticSnapshot());
report["nearby_visible_count"]=Measure("nearby_projection",()=>RegionalCampaign.Nearby(snapshot,session.PlayerControl)).Length;
var bytes=Measure("serialize",()=>ContractJson.Write(snapshot));report["payload_bytes"]=bytes.Length;
var restored=Measure("restore",()=>new WorldSession(ContractJson.Read<ContractWorld>(bytes)));
if(ContractJson.CanonicalHash(restored.DiagnosticSnapshot())!=ContractJson.CanonicalHash(snapshot))throw new InvalidDataException("Restore differs");
Measure("continue_restored",()=>{foreach(var s in new[]{session,restored})while(s.Seconds<10){s.SetPaused(false);s.AdvanceTo(10);}return session.Seconds;});
if(ContractJson.CanonicalHash(restored.DiagnosticSnapshot())!=ContractJson.CanonicalHash(session.DiagnosticSnapshot()))throw new InvalidDataException("Future differs");
report["future_hash"]=ContractJson.CanonicalHash(session.DiagnosticSnapshot());report["restore_exact"]=true;report["future_exact"]=true;report["process_peak_working_set"]=Process.GetCurrentProcess().PeakWorkingSet64;
Console.WriteLine("CAPACITY_RESULT "+JsonSerializer.Serialize(report));
